type envelope struct {
    Type    string          `json:"type"`
    Payload json.RawMessage `json:"payload"`
}
var translators = map[string]func(json.RawMessage) (Canonical, error){  // registry
    "csv": fromCSV, "xml": fromXML, "legacy": fromLegacy}
func normalize(raw []byte) (Canonical, error) {
    var e envelope
    if err := json.Unmarshal(raw, &e); err != nil { return Canonical{}, err }
    t, ok := translators[e.Type]
    if !ok { return Canonical{}, fmt.Errorf("unknown wire type %q", e.Type) }
    return t(e.Payload)                 // consumers see one canonical shape
}
